|QuestSub = ...
|QuestStep1 = Give a 20kg+ [[Gold]] to the Vagrant
|Rewards = {{EXP|100,000}} • {{Sand Dollars|100}} • {{Meteor Shards|250}}
}}

= Dialogue =

