templates.Template:Equipment/styles.css:
.equip-table { width:100%; table-layout:auto; }
.equip-table th, .equip-table td { vertical-align:middle; text-align:center; }
.equip-table > caption{
  display: table-caption;       
  caption-side: top;
  width: 100% !important;
  max-width: 100%;
  box-sizing: border-box;
  white-space: normal;         
  overflow-wrap: anywhere;      
}

/* Appearance */
.equip-cell-img { width:72px; }
.equip-icon { display:block; margin:4px auto; image-rendering:pixelated; object-fit:contain; }

/* Name/desc */
.equip-cell-name { text-align:center; }
.e-desc { color:#cfd8dc; font-weight:400; font-size:13px; display:block; margin-top:2px; }

/* Slot/recipe */
.equip-cell-slot, .equip-cell-recipe { font-size:13px; }

/* Price */
.equip-cell-price { white-space:nowrap; }
.equip-cell-price .price-amt { color:#B2B277; font-weight:700; }

/* Stats cell */
.equip-cell-stats{
  padding:8px 10px;
  font-size:13px;
  line-height:1.2;
  min-width:240px;
  white-space:normal !important;
}

.equip-stats{
  display:grid !important;
  grid-template-columns: auto auto;   /* label | value */
  column-gap:10px;                    /* ← space between label and value */
  row-gap:6px;                        /* space between rows */
  justify-content:center;
  align-items:center;
  margin:0;
}

.equip-stat { display:contents; }     /* let label+value occupy the two grid cells */

.stat-label{
  justify-self:end;                   /* right-align labels */
  font-weight:700;
}

.stat-val{
  justify-self:start;                 /* left-align values */
  font-weight:700;
  color:#fff;
}

/* 6★ divider */
.equip-6star{
  margin:8px auto 6px;
  text-align:center;
  opacity:.85;
  border-top:1px solid #ffffff30;
  padding-top:4px;
  font-size:12px;
  letter-spacing:.5px;
  width:90%;
}

