templates.Template:Events/styles.css:
/* hourly event wrapper */
.countdown-events {
	display: flex;
	flex-wrap: wrap;
	color: #EEEEEE;
	margin: 10px;
	justify-content: center;
}

/* single card */
.event-cell {
	display: flex;
	align-items: center;
	flex-direction: column;
	background-image: linear-gradient(rgba(0,0,0,0.85), rgba(0,0,0,0.85));
	/* fixed theme color */
	background-color: #AAEEFF;
	border: 2px solid #AAEEFF;
	border-radius: 10px;
	padding: 10px;
	width: 100%;
	max-width: 420px;
	min-width: 240px;
	margin: 10px;
	position: relative;
}

/* active/current state */
.event-cell.current-event {
	background-image: linear-gradient(rgba(0,0,0,0.65), rgba(0,0,0,0.85));
	background-color: #AAEEFF;
}

/* title + label */
.current-label {
	padding-left: 4px;
	font-weight: 500;
	opacity: 0.75;
	font-size: 12px;
}

/* highlight name when current */
.current-event .season-name {
	color: #AAEEFF;
	font-weight: 700;
}

/* icon/label swap */
.event-cell .active-icon,
.event-cell .current-label { display: none; }

.event-cell.current-event .active-icon,
.event-cell.current-event .current-label { display: inline-block; }

.event-cell.current-event .inactive-icon { display: none; }

/* countdown text */
.season-cd { text-align: center; }
.season-cd-content {
	color: #AAEEFF;
	font-weight: 700;
}

/* icon wrapper */
.season-icon { line-height: 0; }

