.shovel-cell-img { width: 72px; text-align: center; }
.shovel-icon { display: block; margin: 4px auto; image-rendering: pixelated; object-fit: contain; }

.s-desc { color: #cfd8dc; font-weight: 400; font-size: 13px; }

.shovel-cell-price { text-align: right; white-space: nowrap; }
.shovel-cell-loc { white-space: nowrap; }

/* Stats column */
.shovel-cell-stats {
  padding: 8px 10px;
  font-size: 13px;
  line-height: 1.6; /* Adds clean vertical spacing between the lines */
  min-width: 220px;           
}

/* Force every individual container inside the stats cell to break onto its own new line */
.shovel-cell-stats .shovel-stats,
.shovel-cell-stats div,
.shovel-cell-stats p {
  display: block !important;
  clear: both;
}

/* Keep the labels and values inline horizontally with each other */
.shovel-stats .stat-label,
.shovel-cell-stats .stat-label { 
  color: inherit; 
  display: inline !important;
}   

.shovel-stats .stat-val,
.shovel-cell-stats .stat-val { 
  font-weight: 700; 
  color: #fff; 
  display: inline !important;
  margin-left: 4px; /* Space between the colon and the number */
}

templates.Template:QuestMastery/styles.css:
