templates.Template:SocialLink/styles.css:
/* Template copied from the Dig Wiki [https://digtionary.org/wiki/Template:Mainnav] This Template is licensed under CC-BY-NC-SA. */
.social-buttons-container {
  display: flex;
  justify-content: center;
}

.social-buttons {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
}

.social-button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  background-color: rgba(0, 0, 0, 0.2);
  border-radius: 8px;
  text-decoration: none;
  color: #fff;
  font-size: 14px;
  transition: transform 0.3s;
}

.social-button span {
  font-weight: bold;
}

.social-button img {
	margin-right: 4px;
    vertical-align: middle;
    position: relative;
    bottom: 1.2px;
}

.social-button:hover {
  transform: translateY(-2px);
}

.social-button.twitter {
  background-color: #000000;
  color: #fff;
}

.social-button.discord {
  background-color: #5865F2;
  color: #fff;
}

.social-button.youtube {
  background-color: #FF0000;
  color: #fff;
}

.roblox {
	background-color: #355fff;
	color: #fff;
}

